+  /// Whether any active shell job has an unconsumed quiet-threshold
+  /// crossing (gh-1459 ask #4) — the same crossing check
+  /// [_steerHeadlessLiveness] applies after the wake. An instant drain
+  /// wake is legitimate exactly when such a crossing waits to be
+  /// consumed; with nothing to consume it is scheduler pathology (see
+  /// [headlessDrainRoundSleep]).
+  bool _headlessSteerDue(
+    List<ShellJobEntry> active,
+    _HeadlessDrainLiveness liveness,
+  ) {
+    if (liveness.quietMs <= 0) return false;
+    for (final job in active) {
+      if (!job.isRunning || !job.notifyOnSettle) continue;
+      final elapsed = _waitingClock().difference(job.startedAt);
+      final elapsedMs = elapsed.isNegative ? 0 : elapsed.inMilliseconds;
+      if (elapsedMs ~/ liveness.quietMs >
+          (liveness.consumedBucket[job.id] ?? 0)) {
+        return true;
+      }
+    }
+    return false;
+  }
+
   /// Steers the due interim liveness notices of the active shell jobs
   /// (gh-1459 ask #4): one compact `<system-notice>` per newly-crossed
   /// quiet threshold (`job <id> running · <elapsed> elapsed · tail: …`
diff --git a/lib/src/cli/headless_config.dart b/lib/src/cli/headless_config.dart
index e287b48ee..36ce1edb9 100644
--- a/lib/src/cli/headless_config.dart
+++ b/lib/src/cli/headless_config.dart
@@ -138,6 +138,27 @@ String headlessDrainDetachCause({
   required bool roundCapEnded,
 }) => roundCapEnded ? 'round cap (10 rounds)' : 'drain ceiling ($drainMs ms)';

+/// The ceiling sleep of one headless drain round (gh-1459): [wake] — the
+/// pure `wakeIn` bound — unless it is a non-positive instant wake with NO
+/// due liveness crossing ([steerDue] false). A zero/negative
+/// `Future.delayed` completes at once, and a round that neither settles a
+/// job nor consumes a crossing then burns the 10-round cap before the
+/// wall ceiling spends a millisecond — the 2026-10-11 red main (run
+/// 38120494810, hostile-env leg): a never-settling job detached on
+/// 'round cap (10 rounds)' instead of the documented 'drain ceiling'.
+/// Such a round sleeps the [remainingCeiling] instead, so a never-settling
+/// job always reaches its ceiling; a due steer keeps the instant wake (the
+/// steer fires right after the round, on cadence). Pure — unit-tested
+/// directly.
+Duration headlessDrainRoundSleep({
+  required Duration wake,
+  required bool steerDue,
+  required Duration remainingCeiling,
+}) {
+  if (wake > Duration.zero || steerDue) return wake;
+  return remainingCeiling;
+}
+
