/// What one round of the headless background-job drain does right now
/// (gh-1459). Pure — unit-tested directly.
enum HeadlessDrainAction {
  /// Active jobs exist and the ceiling still has budget: keep draining.
  drain,

  /// Nothing active: the run may exit.
  exit,

  /// The wall-clock ceiling is spent (or disabled): detach with the
  /// waiting summary — the documented degradation, never a hang.
  detach,
}

/// The drain decision for one round (gh-1459): active jobs keep draining
/// while the ceiling has budget; nothing active exits; a spent ceiling
/// detaches. With [shellDrainDisabled] (`shellJobDrainMs: 0`) the kill
/// switch is shell-job-scoped: shell jobs detach immediately, while the
/// pre-gh-1459 subagent drain stays unconditional (the `0` edge never
/// detaches more than the predecessor did for subagent-only waits).
/// Pure — unit-tested directly.
HeadlessDrainAction headlessJobDrainAction({
  required bool hasActiveSubAgents,
  required bool hasActiveShellJobs,
  required DateTime now,
  required DateTime deadline,
  bool shellDrainDisabled = false,
}) {
  if (!hasActiveSubAgents && !hasActiveShellJobs) {
    return HeadlessDrainAction.exit;
  }
  if (shellDrainDisabled) {
    // Shell-job-scoped kill switch: a live shell job detaches at once;
    // in-flight subagents keep the legacy unconditional drain.
    return hasActiveShellJobs
        ? HeadlessDrainAction.detach
        : HeadlessDrainAction.drain;
  }
  if (!now.isBefore(deadline)) return HeadlessDrainAction.detach;
  return HeadlessDrainAction.drain;
}

/// The cause clause of the drain's detach line (gh-1459): the wall-clock
/// ceiling when it spent the budget, the 10-round cap when the loop
/// exhausted while the ceiling still had one — never a misattribution.
/// Pure — unit-tested directly.
String headlessDrainDetachCause({
  required int drainMs,
  required bool roundCapEnded,
}) => roundCapEnded ? 'round cap (10 rounds)' : 'drain ceiling ($drainMs ms)';

/// The ceiling sleep of one headless drain round (gh-1459): [wake] — the
/// pure `wakeIn` bound — unless it is a non-positive instant wake with NO
/// due liveness crossing ([steerDue] false). A zero/negative
/// `Future.delayed` completes at once, and a round that neither settles a
/// job nor consumes a crossing then burns the 10-round cap before the
/// wall ceiling spends a millisecond — the 2026-10-11 red main (run
/// 38120494810, hostile-env leg): a never-settling job detached on
/// 'round cap (10 rounds)' instead of the documented 'drain ceiling'.
/// Such a round sleeps the [remainingCeiling] instead, so a never-settling
/// job always reaches its ceiling; a due steer keeps the instant wake (the
/// steer fires right after the round, on cadence). Pure — unit-tested
/// directly.
Duration headlessDrainRoundSleep({
  required Duration wake,
  required bool steerDue,
  required Duration remainingCeiling,
}) {
  if (wake > Duration.zero || steerDue) return wake;
  return remainingCeiling;
}

/// What the drain's liveness leg does for one still-running awaited shell
/// job right now (gh-1459 ask #4). Pure — unit-tested directly.
enum HeadlessLivenessAction {
  /// A new quiet threshold was crossed and the model has not probed the
  /// job since the last consumption point: steer ONE notice now.
  steer,

  /// A threshold crossed but the model probed the job (its own
  /// `bash_job status/output`) since the last consumption point: skip
  /// this crossing — it is consumed, so the next steer waits for the
  /// NEXT threshold (never a per-timer retry of the same one).
  skip,

  /// No new threshold crossed yet (or liveness disabled): keep waiting.
  wait,
}

/// The liveness decision for one still-running job (gh-1459 ask #4):
/// [elapsedMs] measured from the job's start, bucketed by [quietMs];
/// [lastConsumedBucket] is the last bucket already steered or skipped;
/// [probedSinceLastConsumption] is whether the model probed the job
/// after that consumption. Pure — unit-tested directly.
HeadlessLivenessAction headlessJobLivenessAction({
  required int elapsedMs,
  required int quietMs,
  required int lastConsumedBucket,
  required bool probedSinceLastConsumption,
}) {
  if (quietMs <= 0) return HeadlessLivenessAction.wait;
  final bucket = elapsedMs ~/ quietMs;
  if (bucket == 0 || bucket <= lastConsumedBucket) {
    return HeadlessLivenessAction.wait;
  }
  if (probedSinceLastConsumption) return HeadlessLivenessAction.skip;
  return HeadlessLivenessAction.steer;
}

/// The elapsed clause of the liveness notice (gh-1459 ask #4): "12m"
/// from the first minute up, "45s" below it. A negative input (the
/// fake-clock test seam — `ShellJobEntry.startedAt` is real
/// `DateTime.now()` while the waiting clock may sit behind it) clamps
/// to "0s", never a "-3s" clause. Pure — unit-tested directly.
String headlessLivenessElapsedText(Duration elapsed) {
  final clamped = elapsed.inMilliseconds < 0 ? 0 : elapsed.inMilliseconds;
  final d = Duration(milliseconds: clamped);
  return d.inMinutes >= 1 ? '${d.inMinutes}m' : '${d.inSeconds}s';
}

