      // The `0` kill switch is shell-job-scoped: a subagent-only round
      // is the legacy pre-gh-1459 drain — await the settles directly,
      // with no ceiling sleep (a zero deadline would wake it at once
      // and spin the round cap).
      await Future.wait(waits);
    } else {
      final now = _waitingClock();
      await Future.any([
        Future.wait(waits),
        _waitingSleep(
          headlessDrainRoundSleep(
            wake: liveness.wakeIn(shellActive, now, deadline),
            steerDue: _headlessSteerDue(shellActive, liveness),
            remainingCeiling: deadline.difference(now),
