    for (final job in _shellJobs.jobs)
      if (job.isRunning && job.notifyOnSettle) job,
  ];

  bool _headlessSubAgentsActive() => _taskConfig.jobManager.jobs.any(
    (job) =>
        job.status == TaskJobStatus.queued ||
        job.status == TaskJobStatus.running,
