  bool _headlessSteerDue(
    List<ShellJobEntry> active,
    _HeadlessDrainLiveness liveness,
  ) {
    if (liveness.quietMs <= 0) return false;
    for (final job in active) {
      if (!job.isRunning || !job.notifyOnSettle) continue;
