  HeadlessDrainAction _headlessDrainAction(
    DateTime deadline, {
    required bool shellDrainDisabled,
  }) => headlessJobDrainAction(
    hasActiveSubAgents: _headlessSubAgentsActive(),
    hasActiveShellJobs: _headlessActiveShellJobs().isNotEmpty,
